	logic        sd1_pipe_ack;
	logic [31:0] sd1_pipe_rdat;
	wb_cfg_pipe #(.PIPE(4), .AW(32), .TW(0)) u_sd1_pipe (
		.clk(clk),
		.rst_n(rst_n),
		.m_cyc(slot_sel[SLOT_SD1] & g_cyc),
		.m_stb(slot_sel[SLOT_SD1] & g_stb),
		.m_we(g_we),
		.m_adr(slot_sel[SLOT_SD1] ? g_adr & ~32'hfffffff0 : 32'd0),
		.m_dat(g_wdata),
		.m_sel(g_sel),
		.m_ack(sd1_pipe_ack),
		.m_rdat(sd1_pipe_rdat),
		.s_cyc(sd1_i_wb_cyc),
		.s_stb(sd1_i_wb_stb),
		.s_we(sd1_i_wb_we),
		.s_adr(sd1_i_wb_adr),
		.s_dat(sd1_i_wb_dat),
		.s_sel(sd1_i_wb_sel),
		.s_ack(sd1_o_wb_ack),
		.s_rdat(sd1_o_wb_dat)
	);

	//------------------------------------------------------------------------------
