		.m_we(g_we),
		.m_adr(slot_sel[SLOT_DMA0] ? g_adr & ~32'hfffffff0 : 32'd0),
		.m_dat(g_wdata),
		.m_sel(g_sel),
		.m_ack(dma0_pipe_ack),
		.m_rdat(dma0_pipe_rdat),
		.s_cyc(dma0_i_wb_cyc),
		.s_stb(dma0_i_wb_stb),
		.s_we(dma0_i_wb_we),
		.s_adr(dma0_i_wb_adr),
		.s_dat(dma0_i_wb_dat),
		.s_sel(dma0_i_wb_sel),
		.s_ack(dma0_o_wb_ack),
		.s_rdat(dma0_o_wb_dat)
	);

	//------------------------------------------------------------------------------
	//  Slave dma1 — wb_cfg_pipe PIPE=1 (posted write / blocking read)
	//------------------------------------------------------------------------------
	logic        dma1_pipe_ack;
	logic [31:0] dma1_pipe_rdat;
	wb_cfg_pipe #(.PIPE(1), .AW(32), .TW(0)) u_dma1_pipe (
		.clk(clk),
		.rst_n(rst_n),
		.m_cyc(slot_sel[SLOT_DMA1] & g_cyc),
		.m_stb(slot_sel[SLOT_DMA1] & g_stb),
		.m_we(g_we),
		.m_adr(slot_sel[SLOT_DMA1] ? g_adr & ~32'hfffffff0 : 32'd0),
		.m_dat(g_wdata),
		.m_sel(g_sel),
		.m_ack(dma1_pipe_ack),
		.m_rdat(dma1_pipe_rdat),
		.s_cyc(dma1_i_wb_cyc),
		.s_stb(dma1_i_wb_stb),
		.s_we(dma1_i_wb_we),
		.s_adr(dma1_i_wb_adr),
		.s_dat(dma1_i_wb_dat),
		.s_sel(dma1_i_wb_sel),
		.s_ack(dma1_o_wb_ack),
		.s_rdat(dma1_o_wb_dat)
	);

	//------------------------------------------------------------------------------
	//  Slave sha256_0 — wb_cfg_pipe PIPE=2 (posted write / blocking read)
	//------------------------------------------------------------------------------
	logic        sha256_0_pipe_ack;
	logic [31:0] sha256_0_pipe_rdat;
	wb_cfg_pipe #(.PIPE(2), .AW(32), .TW(0)) u_sha256_0_pipe (
		.clk(clk),
		.rst_n(rst_n),
		.m_cyc(slot_sel[SLOT_SHA256_0] & g_cyc),
		.m_stb(slot_sel[SLOT_SHA256_0] & g_stb),
		.m_we(g_we),
		.m_adr(slot_sel[SLOT_SHA256_0] ? g_adr & ~32'hffffffc0 : 32'd0),
		.m_dat(g_wdata),
		.m_sel(g_sel),
		.m_ack(sha256_0_pipe_ack),
		.m_rdat(sha256_0_pipe_rdat),
		.s_cyc(sha256_0_i_wb_cyc),
		.s_stb(sha256_0_i_wb_stb),
		.s_we(sha256_0_i_wb_we),
		.s_adr(sha256_0_i_wb_adr),
		.s_dat(sha256_0_i_wb_dat),
		.s_sel(sha256_0_i_wb_sel),
		.s_ack(sha256_0_o_wb_ack),
		.s_rdat(sha256_0_o_wb_dat)
	);

	//------------------------------------------------------------------------------
	//  Slave sha256_1 — wb_cfg_pipe PIPE=4 (posted write / blocking read)
	//------------------------------------------------------------------------------
	logic        sha256_1_pipe_ack;
	logic [31:0] sha256_1_pipe_rdat;
	wb_cfg_pipe #(.PIPE(4), .AW(32), .TW(0)) u_sha256_1_pipe (
		.clk(clk),
		.rst_n(rst_n),
		.m_cyc(slot_sel[SLOT_SHA256_1] & g_cyc),
		.m_stb(slot_sel[SLOT_SHA256_1] & g_stb),
		.m_we(g_we),
		.m_adr(slot_sel[SLOT_SHA256_1] ? g_adr & ~32'hffffffc0 : 32'd0),
