	);

	//------------------------------------------------------------------------------
	//  Slave smoke — wb_cfg_pipe PIPE=3 (posted write / blocking read)
	//------------------------------------------------------------------------------
	logic        smoke_pipe_ack;
	logic [31:0] smoke_pipe_rdat;
	wb_cfg_pipe #(.PIPE(3), .AW(32), .TW(2)) u_smoke_pipe (
		.clk(clk),
		.rst_n(rst_n),
		.m_cyc(slot_sel[SLOT_SMOKE] & g_cyc),
		.m_stb(slot_sel[SLOT_SMOKE] & g_stb),
		.m_we(g_we),
		.m_adr(slot_sel[SLOT_SMOKE] ? g_adr & ~32'hffffffc0 : 32'd0),
		.m_dat(g_wdata),
		.m_sel(g_sel),
		.m_tga(g_tga[1:0]),
		.m_ack(smoke_pipe_ack),
		.m_rdat(smoke_pipe_rdat),
		.s_cyc(smoke_i_wb_cyc),
		.s_stb(smoke_i_wb_stb),
		.s_we(smoke_i_wb_we),
		.s_adr(smoke_i_wb_adr),
		.s_dat(smoke_i_wb_dat),
		.s_sel(smoke_i_wb_sel),
		.s_tga(smoke_i_wb_tga),
		.s_ack(smoke_o_wb_ack),
		.s_rdat(smoke_o_wb_dat)
	);

	logic [31:0] rsp_dat;
	logic        rsp_ack;

	assign rsp_dat = ({32{slot_sel[SLOT_SRAM]}} & sram_pipe_rdat)
	               | ({32{slot_sel[SLOT_FLASH_XIP]}} & flash_xip_pipe_rdat)
	               | ({32{slot_sel[SLOT_FLASH_CFG]}} & flash_cfg_o_wb_dat)
	               | ({32{slot_sel[SLOT_UART]}} & uart_pipe_rdat)
	               | ({32{slot_sel[SLOT_TESTOUT]}} & testout_pipe_rdat)
	               | ({32{slot_sel[SLOT_SD0]}} & sd0_pipe_rdat)
	               | ({32{slot_sel[SLOT_SD1]}} & sd1_pipe_rdat)
	               | ({32{slot_sel[SLOT_DMA0]}} & dma0_pipe_rdat)
	               | ({32{slot_sel[SLOT_DMA1]}} & dma1_pipe_rdat)
	               | ({32{slot_sel[SLOT_SHA256_0]}} & sha256_0_pipe_rdat)
	               | ({32{slot_sel[SLOT_SHA256_1]}} & sha256_1_pipe_rdat)
	               | ({32{slot_sel[SLOT_SMOKE]}} & smoke_pipe_rdat);
	assign rsp_ack = (unmapped & g_stb)
	               | (sram_pipe_ack)
	               | (flash_xip_pipe_ack)
	               | (slot_sel[SLOT_FLASH_CFG] & flash_cfg_o_wb_ack)
	               | (uart_pipe_ack)
	               | (testout_pipe_ack)
	               | (sd0_pipe_ack)
	               | (sd1_pipe_ack)
	               | (dma0_pipe_ack)
	               | (dma1_pipe_ack)
	               | (sha256_0_pipe_ack)
	               | (sha256_1_pipe_ack)
	               | (smoke_pipe_ack);

	//------------------------------------------------------------------------------
	//  Master response: only the granted slot sees DAT/ACK
	//------------------------------------------------------------------------------
	assign cpu_i_wb_dat   = {32{gsel[0]}} & rsp_dat;
	assign cpu_i_wb_ack   = gsel[0] & rsp_ack;
	assign dma0m_i_wb_dat = {32{gsel[1]}} & rsp_dat;
	assign dma0m_i_wb_ack = gsel[1] & rsp_ack;
	assign dma1m_i_wb_dat = {32{gsel[2]}} & rsp_dat;
	assign dma1m_i_wb_ack = gsel[2] & rsp_ack;

endmodule
